def isMonotonic(A):
    inc, dec = False, False

    for i in range(len(A) - 1):
        if A[i] < A[i+1]:
            inc = True
        if A[i] > A[i+1]:
            dec = True

        if inc and dec:
            return False

    return True
```
</solution>

